`timescale 1ns/1ps
// Optional post-mix chain. Generated bypass stages preserve original timing.
// Process one complete mono PCM sample per in_valid; no sample-rate clock domain.
module pcm_fx_chain #(
    parameter DC_ENABLE=0,
    parameter TREMOLO_ENABLE=0,
    parameter TONE_ENABLE=0,
    parameter DELAY_ENABLE=0,
    parameter REVERB_ENABLE=0
)(
    input clk, input rst,
    input signed [15:0] in_pcm, input in_valid,
    input [1:0] tone_mode,
    output signed [15:0] out_pcm, output out_valid,
    output fault,
    input [15:0] reverb_wet, input [1:0] reverb_room, input dry_play
);
    wire signed [15:0] s_dc, s_trm, s_tone;
    wire v_dc, v_trm, v_tone;
    wire signed [15:0] s_delay,s_reverb;
    wire v_delay,v_reverb,delay_fault,reverb_fault;
    generate if (DC_ENABLE != 0) begin: dc_stage
        pcm_dc_block dc(.clk(clk),.rst(rst),.in_pcm(in_pcm),.in_valid(in_valid),
                        .bypass(1'b0),.out_pcm(s_dc),.out_valid(v_dc));
    end else begin: dc_bypass
        assign s_dc=in_pcm;
        assign v_dc=in_valid;
    end endgenerate
    generate if (TREMOLO_ENABLE != 0) begin: trm_stage
        pcm_tremolo #(.DEPTH(160),.RATE_STEP(1049)) trm(
            .clk(clk),.rst(rst),.in_pcm(s_dc),.in_valid(v_dc),
            .bypass(dry_play),.out_pcm(s_trm),.out_valid(v_trm));
    end else begin: trm_bypass
        assign s_trm=s_dc;
        assign v_trm=v_dc;
    end endgenerate
    generate if (TONE_ENABLE != 0) begin: tone_stage
        pcm_tone_filter tone(.clk(clk),.rst(rst),.in_pcm(s_trm),.in_valid(v_trm),
                             .tone_mode(tone_mode),.out_pcm(s_tone),.out_valid(v_tone));
    end else begin: tone_bypass
        assign s_tone=s_trm;
        assign v_tone=v_trm;
    end endgenerate
    generate if (DELAY_ENABLE != 0) begin: delay_stage
        pcm_delay #(.DELAY_SAMPLES(4096),.WET_SHIFT(1),.FEEDBACK_SHIFT(2)) echo(
            .clk(clk),.rst(rst),.in_pcm(s_tone),.in_valid(v_tone),
            .bypass(dry_play),.out_pcm(s_delay),.out_valid(v_delay),.fault(delay_fault));
    end else begin: delay_bypass
        assign s_delay=s_tone;
        assign v_delay=v_tone;
        assign delay_fault=1'b0;
    end endgenerate
    generate if (REVERB_ENABLE != 0) begin: reverb_stage
        pcm_reverb reverb(.clk(clk),.rst(rst),.in_pcm(s_delay),.in_valid(v_delay),
            .bypass(dry_play),.wet_target(reverb_wet),.room_size(reverb_room),
            .out_pcm(s_reverb),.out_valid(v_reverb),.fault(reverb_fault),.busy());
    end else begin: reverb_bypass
        assign s_reverb=s_delay;
        assign v_reverb=v_delay;
        assign reverb_fault=1'b0;
    end endgenerate
    assign fault=delay_fault|reverb_fault;
    assign out_pcm=fault ? 16'sd0 : s_reverb;
    assign out_valid=v_reverb;
endmodule
